# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _student(last, first):
    return Student("1", last, first, "A")


class SeatingTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        students = [
            _student("Halloway", "Juno"),
            _student("Zed", "Amy"),
            _student("Dunmere", "Piet")
        ]
        self.assertEqual(
            seating_rows(students, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Zed, Amy"
            ],
        )

    def test_bad_seat_count(self):
        students = [_student("Zed", "Amy")]
        for seats in (0, -1):
            with self.assertRaises(ProjectError):
                seating_rows(students, seats)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seating_rows([], 3)


if __name__ == "__main__":
    unittest.main()
